// generated by ios/scripts/build-bridge.sh and gitignored; build it before
// resolving this package.
import PackageDescription

let package = Package(
    name: "SenecaEngine",
    platforms: [.iOS("26.0")],
    products: [
        .library(name: "SenecaEngine", targets: ["SenecaEngine"]),
    ],
    targets: [
        .binaryTarget(name: "SenecaBridgeCore", path: "Frameworks/SenecaBridgeCore.xcframework"),
        .target(name: "SenecaEngine", dependencies: ["SenecaBridgeCore"]),
    ]
)
